esbmc_test_source:
contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // We will call deposit with some amount, then try to withdraw that amount to observe recorded balance effect.
    function run(uint256 depositAmount, uint256 withdrawAttempt) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (depositAmount)); require(depositAmount <= 1000000000000000000000000000000);
        require(address(this).balance >= depositAmount, "insufficient test balance");
        // Ensure depositAmount > 0 to make the rule meaningful
        require(depositAmount > 0);

        // Record contract balance before deposit
        uint256 beforeContractBalance = address(c).balance;

        // Perform deposit sending Ether to c
        c.deposit{value: depositAmount}(); if (__ESBMC_reverted()) return;

        // After deposit, contract balance must have increased by at least depositAmount
        uint256 afterContractBalance = address(c).balance;

        // Try to withdraw withdrawAttempt and record whether it reverted
        bool withdrew;
        c.withdraw(withdrawAttempt); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            withdrew = false;
        } else {
            withdrew = true;
        }

        // If withdraw succeeded, that implies the contract allowed withdrawing at most the recorded balance for this caller.
        // General rule asserted: deposit increased contract balance by exactly depositAmount, and deposit cannot make the contract balance smaller.
        // Also, if withdraw succeeded, then after a successful withdraw the contract balance is <= afterContractBalance (monotone nonincrease due to withdraw).
        assert(
            // contract balance increased by at least depositAmount
            afterContractBalance >= beforeContractBalance + depositAmount
            // additionally, if withdraw succeeded then contract balance decreased (or stayed same) compared to afterContractBalance
            && (withdrew == false || address(c).balance <= afterContractBalance)
        );
    }

    receive() external payable { }
}

