// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Wallet} from "../src/Wallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Wallet c;

    function setUp() public {
        c = new Wallet();
    }

    function _run(uint256 depositAmount, uint256 withdrawAttempt) internal {
        depositAmount = bound(depositAmount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= depositAmount);
        vm.assume(depositAmount > 0);
        uint256 beforeContractBalance = address(c).balance;
        try c.deposit{value: depositAmount}() {} catch { return; }
        uint256 afterContractBalance = address(c).balance;
        bool withdrew;
        try c.withdraw(withdrawAttempt) {
            withdrew = true;
        } catch {
            withdrew = false;
        }
        assertTrue(afterContractBalance >= beforeContractBalance + depositAmount
            // additionally, if withdraw succeeded then contract balance decreased (or stayed same) compared to afterContractBalance
            && (withdrew == false || address(c).balance <= afterContractBalance));
    }

    function testFuzz_run(uint256 depositAmount, uint256 withdrawAttempt) public {
        _run(depositAmount, withdrawAttempt);
    }

    receive() external payable { }
}
